/* @autogenerated */
import { CommonModule } from '@angular/common';
import { Component, computed, DestroyRef, effect, inject, input, linkedSignal, output, signal } from '@angular/core';
import { takeUntilDestroyed, toObservable } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatIconModule } from '@angular/material/icon';
import { MatInputModule } from '@angular/material/input';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { MatSelectModule } from '@angular/material/select';
import { TranslocoModule, TranslocoService } from '@jsverse/transloco';
import { combineLatest, of, switchMap, take } from 'rxjs';
import { Acl } from '@shared/data/acl/acl.model';
import { parseCell } from './cell-parse';
import { matchColumns } from './column-match';
import { IMPORT_ACCEPT, readWorkbook } from './excel-reader';
import { downloadTemplate } from './excel-writer';
import { EntityImportService } from './entity-import.service';
import {
  ImportColumn,
  ImportDefinition,
  ImportMessage,
  ImportParsing,
  ImportPlan,
  ImportPlanColumn,
  ImportRow,
  ImportSheet,
} from './entity-import.model';

/** Campos que nunca llegan en el Excel: los asigna el sistema. */
const SYSTEM_FIELDS = ['uid', 'version'];
/** Filas que se muestran de la vista previa; se pueden pedir más. */
const PREVIEW_ROWS = 50;
/** Cada cuánto se comprueba si sigue viva una importación que ejecuta otra pestaña. */
const REFRESH_MS = 10_000;

/** Columna esperada, con su etiqueta traducida y si es clave u obligatoria. */
interface ExpectedColumn extends ImportColumn {
  text: string;
  key: boolean;
  /** De solo lectura: se lleva al valor del Excel con una de sus acciones tras guardar. */
  viaAction?: boolean;
}

/** Cabecera del Excel con la posición de su columna. */
interface SheetHeader {
  text: string;
  index: number;
}

/** Errores de una fila que se detectan sin el servidor: celdas que no se pueden leer y claves vacías. */
interface RowCheck {
  row: ImportRow;
  /** Motivos de cada celda con error, por posición de la columna. */
  cells: Record<number, ImportMessage[]>;
  messages: ImportMessage[];
}

/**
 * Importación de elementos desde un Excel: lee el fichero, propone qué cabecera corresponde a cada campo
 * (por parecido con su etiqueta) y crea o actualiza cada fila buscándola por la clave natural.
 *
 * Solo se ofrecen los campos que el ACL genérico deja escribir, sin `uid` ni `version` y sin los que fija el
 * contexto global (p. ej. el tenant elegido en la barra superior), que se aplican a todas las filas.
 *
 * La importación sigue en segundo plano al cerrar la pantalla; al volver se muestra su estado.
 */
@Component({
  selector: 'entity-import',
  standalone: true,
  imports: [
    CommonModule,
    MatButtonModule,
    MatFormFieldModule,
    MatIconModule,
    MatInputModule,
    MatProgressBarModule,
    MatSelectModule,
    TranslocoModule,
  ],
  templateUrl: './entity-import.component.html',
  styleUrl: './entity-import.component.scss',
})
export class EntityImportComponent {
  readonly definition = input.required<ImportDefinition<any>>();
  readonly closed = output<void>();

  readonly accept = IMPORT_ACCEPT;

  private readonly imports = inject(EntityImportService);
  private readonly transloco = inject(TranslocoService);

  private readonly storageKey = computed(() => this.definition().storageKey);
  readonly job = computed(() => this.imports.job(this.storageKey())());
  readonly runningHere = computed(() => this.imports.isRunningHere(this.storageKey()));
  readonly runningElsewhere = computed(() => this.job()?.status === 'running' && !this.runningHere());
  readonly canResume = computed(() => {
    this.job();
    return this.imports.canResume(this.storageKey());
  });
  readonly progress = computed(() => {
    const job = this.job();
    return job?.total ? (100 * job.processed) / job.total : 0;
  });
  readonly failures = computed(() => this.job()?.outcomes.filter((o) => o.result === 'failed') ?? []);
  readonly successes = computed(() => this.job()?.outcomes.filter((o) => o.result !== 'failed') ?? []);
  readonly warnings = computed(() => this.successes().filter((o) => o.messages?.length));

  readonly reading = signal(false);
  readonly downloading = signal(false);
  readonly readFailed = signal(false);
  readonly fileName = signal('');
  readonly sheets = signal<ImportSheet[]>([]);
  readonly sheetIndex = signal(0);
  readonly sheet = computed<ImportSheet | undefined>(() => this.sheets()[this.sheetIndex()]);

  private readonly acl = signal<Acl | undefined>(undefined);
  /** Textos traducidos por clave (etiquetas de los campos y de las opciones). */
  private readonly texts = signal<Record<string, string>>({});

  /** Campos que fija el contexto de la entidad (según su repositorio) y que se aplican a todas las filas. */
  readonly fixedColumns = computed(() => {
    const fixed = Object.keys(this.definition().target.context?.().fixed ?? {});
    return this.allColumns().filter((column) => fixed.includes(column.field));
  });
  /** Columnas que se pueden leer del Excel: las claves y las que el ACL deja escribir. */
  /**
   * Columnas que se pueden leer del Excel: las claves, las que el ACL deja escribir y las de solo lectura que alguna
   * acción permitida puede cambiar. Las ocultas por el ACL no se ofrecen.
   */
  readonly columns = computed<ExpectedColumn[]>(() => {
    const fields = this.acl()?.fields;
    const hidden = fields?.noVisibles ?? [];
    const readOnly = fields?.noEditables ?? [];
    const fixed = this.fixedColumns().map((column) => column.field);
    return this.allColumns().flatMap((column) => {
      if (fixed.includes(column.field)) {
        return [];
      }
      if (column.key || (!hidden.includes(column.field) && !readOnly.includes(column.field))) {
        return [column];
      }
      return !hidden.includes(column.field) && this.allowedActions(column.field).length
        ? [{ ...column, viaAction: true }]
        : [];
    });
  });
  /** Columnas que el ACL no deja escribir ni cambiar con una acción. */
  readonly forbiddenLabels = computed(() => {
    const offered = this.columns().map((column) => column.field);
    const fixed = this.fixedColumns().map((column) => column.field);
    return this.allColumns()
      .filter((column) => !offered.includes(column.field) && !fixed.includes(column.field))
      .map((column) => column.text)
      .join(', ');
  });
  readonly canCreate = computed(() => this.allowed('create'));
  readonly canUpdate = computed(() => this.allowed('update'));
  readonly aclLoaded = computed(() => this.acl() !== undefined);

  /** Cabecera elegida para cada campo; se propone al cambiar de hoja y se puede corregir. */
  readonly mapping = linkedSignal<Record<string, number | null>>(() => {
    const sheet = this.sheet();
    if (!sheet) {
      return {};
    }
    const candidates = this.columns().map((column) => ({
      field: column.field,
      names: [column.text, column.field, ...(column.aliases ?? [])],
    }));
    return matchColumns(sheet.headers, candidates);
  });
  readonly missingKeys = computed(() => this.columns().filter((c) => c.key && this.mapping()[c.field] == null));
  /**
   * Obligatorios para crear que no llegan del Excel: solo se podrán actualizar elementos existentes. No faltan los que
   * tienen valor inicial (`defaults`) ni los que se aplican con su acción: al crear los pone el backend.
   */
  readonly missingRequired = computed(() => {
    const defaults = (this.definition().defaults?.() ?? {}) as Record<string, unknown>;
    return this.columns().filter(
      (c) => c.required && !c.key && !c.viaAction && defaults[c.field] === undefined && this.mapping()[c.field] == null,
    );
  });
  readonly canStart = computed(
    () => !!this.sheet()?.rows.length && !this.missingKeys().length && (this.canCreate() || this.canUpdate()),
  );
  /** Campos que se pueden importar y no tienen columna. */
  readonly unmappedLabels = computed(() =>
    this.columns()
      .filter((column) => this.mapping()[column.field] == null)
      .map((column) => column.text)
      .join(', '),
  );
  /** Cabeceras con nombre del Excel: las columnas de la vista previa. */
  readonly headers = computed<SheetHeader[]>(() =>
    (this.sheet()?.headers ?? []).flatMap((text, index) => (text ? [{ text, index }] : [])),
  );
  /** Campo asignado a cada cabecera, por su posición. */
  readonly fieldAt = computed<Partial<Record<number, string>>>(() =>
    Object.fromEntries(
      Object.entries(this.mapping()).flatMap(([field, index]) => (index == null ? [] : [[index, field]])),
    ),
  );

  /** Otros textos de sí / no, tal como se escriben (separados por comas). */
  readonly trueText = signal('');
  readonly falseText = signal('');
  readonly monthFirst = signal(false);
  readonly parsing = computed<ImportParsing>(() => ({
    trueWords: splitWords(this.trueText()),
    falseWords: splitWords(this.falseText()),
    monthFirst: this.monthFirst(),
  }));

  /** Columnas emparejadas, tal como se leerán al importar. */
  readonly planColumns = computed<ImportPlanColumn[]>(() => {
    const mapping = this.mapping();
    const texts = this.texts();
    return this.columns()
      .filter((column) => mapping[column.field] != null)
      .map((column) => ({
        field: column.field,
        type: column.type ?? 'text',
        label: column.text,
        index: mapping[column.field]!,
        required: column.required,
        viaAction: column.viaAction,
        options: column.options?.map((option) => ({
          value: option.value,
          names: [option.value, texts[option.label] ?? option.value],
        })),
      }));
  });
  readonly hasBoolean = computed(() => this.planColumns().some((column) => column.type === 'boolean'));
  readonly hasDate = computed(() =>
    this.planColumns().some((column) => column.type === 'date' || column.type === 'datetime'),
  );

  /** Comprobación de cada fila con las columnas y los ajustes elegidos. */
  readonly checks = computed<RowCheck[]>(() => {
    const columns = this.planColumns();
    const parsing = this.parsing();
    const keys = this.definition().keys;
    return (this.sheet()?.rows ?? []).map((row) => {
      const cells: Record<number, ImportMessage[]> = {};
      const messages: ImportMessage[] = [];
      const emptyKeys: ImportPlanColumn[] = [];
      columns.forEach((column) => {
        const parsed = parseCell(row.cells[column.index], column, parsing);
        if ('error' in parsed) {
          cells[column.index] = [parsed.error];
          messages.push(parsed.error);
        } else if (parsed.value === undefined && keys.includes(column.field)) {
          emptyKeys.push(column);
        }
      });
      if (emptyKeys.length) {
        const missing: ImportMessage = {
          key: 'common.import.error.missingKey',
          params: { fields: emptyKeys.map((column) => column.label).join(', ') },
        };
        emptyKeys.forEach((column) => (cells[column.index] = [missing]));
        messages.push(missing);
      }
      return { row, cells, messages };
    });
  });
  readonly failingRows = computed(() => this.checks().filter((check) => check.messages.length).length);
  readonly onlyErrors = signal(false);
  readonly previewLimit = linkedSignal(() => {
    this.sheet();
    return PREVIEW_ROWS;
  });
  private readonly filteredChecks = computed(() =>
    this.onlyErrors() ? this.checks().filter((check) => check.messages.length) : this.checks(),
  );
  readonly preview = computed(() => this.filteredChecks().slice(0, this.previewLimit()));
  readonly hiddenRows = computed(() => this.filteredChecks().length - this.preview().length);

  private readonly allColumns = computed<ExpectedColumn[]>(() => {
    const definition = this.definition();
    const texts = this.texts();
    return definition.columns
      .filter((column) => !SYSTEM_FIELDS.includes(column.field))
      .map((column) => ({
        ...column,
        text: texts[column.label] ?? column.field,
        key: definition.keys.includes(column.field),
      }));
  });

  constructor() {
    const destroyRef = inject(DestroyRef);
    const definition$ = toObservable(this.definition);
    definition$
      .pipe(
        switchMap((definition) => definition.target.acl().pipe(take(1))),
        takeUntilDestroyed(destroyRef),
      )
      .subscribe((acl) => this.acl.set(acl));
    definition$
      .pipe(
        switchMap((definition) => {
          const keys = definition.columns.flatMap((column) => [
            column.label,
            ...(column.options ?? []).map((option) => option.label),
          ]);
          if (!keys.length) {
            return of({});
          }
          return combineLatest(
            Object.fromEntries(keys.map((key) => [key, this.transloco.selectTranslate(key, {}, definition.scope)])),
          );
        }),
        takeUntilDestroyed(destroyRef),
      )
      .subscribe((texts) => this.texts.set(texts as Record<string, string>));

    // Una importación de otra pestaña que deja de latir pasa a interrumpida
    effect((onCleanup) => {
      if (this.runningElsewhere()) {
        const key = this.storageKey();
        const timer = setInterval(() => this.imports.refresh(key), REFRESH_MS);
        onCleanup(() => clearInterval(timer));
      }
    });
  }

  /** Texto de la celda para la vista previa; el de un campo sensible, enmascarado. */
  cellText(row: ImportRow, index: number): string {
    const cell = row.cells[index];
    if (cell === null || cell === undefined || String(cell).trim() === '') {
      return '';
    }
    const field = this.fieldAt()[index];
    if (field && this.definition().sensitive?.includes(field)) {
      return '••••••';
    }
    return cell instanceof Date ? cell.toLocaleString() : String(cell);
  }

  /** Motivos traducidos, uno por línea (para el `title` de la celda o la fila). */
  describe(messages: ImportMessage[] | undefined): string {
    return (messages ?? []).map((message) => this.transloco.translate(message.key, message.params)).join('\n');
  }

  /** Etiqueta con la que se ofrece un campo en el selector de una cabecera. */
  optionText(column: ExpectedColumn): string {
    const badge = column.key ? 'key' : column.viaAction ? 'viaAction' : column.required ? 'required' : null;
    return badge ? `${column.text} (${this.transloco.translate('common.import.mapping.' + badge)})` : column.text;
  }

  /** Asigna un campo a la cabecera `index` (o la deja sin importar con `null`). */
  assignHeader(index: number, field: string | null): void {
    if (field != null) {
      this.assign(field, index);
      return;
    }
    const current = this.fieldAt()[index];
    if (current) {
      this.assign(current, null);
    }
  }

  showMore(): void {
    this.previewLimit.update((limit) => limit + PREVIEW_ROWS);
  }

  async read(event: Event): Promise<void> {
    const target = event.target as HTMLInputElement;
    const file = target.files?.[0];
    target.value = '';
    if (!file) {
      return;
    }
    this.reading.set(true);
    this.readFailed.set(false);
    try {
      const sheets = await readWorkbook(file);
      this.fileName.set(file.name);
      this.sheetIndex.set(
        Math.max(
          0,
          sheets.findIndex((sheet) => sheet.rows.length > 0),
        ),
      );
      this.sheets.set(sheets);
    } catch {
      this.readFailed.set(true);
    } finally {
      this.reading.set(false);
    }
  }

  /**
   * Descarga un Excel en blanco con las columnas que se pueden importar (las mismas etiquetas que reconoce el
   * emparejado) y una hoja de instrucciones con la clave, los obligatorios y el formato de cada columna.
   */
  async downloadTemplate(): Promise<void> {
    const t = (key: string, params?: Record<string, string>) =>
      this.transloco.translate(`common.import.${key}`, params);
    const columns = this.columns();
    this.downloading.set(true);
    try {
      await downloadTemplate(t('template.fileName', { entity: this.storageKey() }), {
        dataSheet: t('template.dataSheet'),
        headers: columns.map((column) => column.text),
        helpSheet: t('template.helpSheet'),
        help: [
          [t('template.column'), t('template.mandatory'), t('template.format')],
          ...columns.map((column) => [
            column.text,
            column.key
              ? t('mapping.key')
              : column.viaAction
                ? t('mapping.viaAction')
                : column.required
                  ? t('mapping.required')
                  : '',
            this.formatOf(column),
          ]),
        ],
      });
    } finally {
      this.downloading.set(false);
    }
  }

  /** Asigna la cabecera al campo; una cabecera solo puede ir a un campo. */
  assign(field: string, index: number | null): void {
    this.mapping.update((current) => {
      const next = { ...current };
      if (index != null) {
        Object.keys(next).forEach((other) => {
          if (next[other] === index) {
            next[other] = null;
          }
        });
      }
      next[field] = index;
      return next;
    });
  }

  back(): void {
    this.sheets.set([]);
    this.fileName.set('');
  }

  start(): void {
    const sheet = this.sheet();
    if (!sheet || !this.canStart()) {
      return;
    }
    const definition = this.definition();
    const columns = this.planColumns();
    const plan: ImportPlan = {
      fileName: this.fileName(),
      columns,
      rows: sheet.rows,
      parsing: this.parsing(),
      missingRequired: this.missingRequired().map((column) => column.text),
      sensitive: columns.some((column) => definition.sensitive?.includes(column.field)),
      allowedActions: Object.keys(definition.actions ?? {}).flatMap((field) =>
        this.allowedActions(field).map((action) => action.name),
      ),
      canCreate: this.canCreate(),
      canUpdate: this.canUpdate(),
    };
    this.imports.start(definition, plan);
    this.back();
  }

  resume(): void {
    this.imports.resume(this.definition());
  }

  cancel(): void {
    this.imports.cancel(this.storageKey());
  }

  /** Descarta el resultado para empezar otra importación. */
  restart(): void {
    this.imports.clear(this.storageKey());
  }

  /** Formato o valores admitidos de una columna, para la hoja de instrucciones. */
  private formatOf(column: ExpectedColumn): string {
    if (column.type === 'enum' && column.options?.length) {
      // Si va por acción, solo los valores a los que lleva alguna acción permitida
      const reachable = this.allowedActions(column.field).map((action) => action.value);
      return column.options
        .filter((option) => !column.viaAction || reachable.includes(option.value))
        .map((option) => this.texts()[option.label] ?? option.value)
        .join(' / ');
    }
    return this.transloco.translate(`common.import.template.type.${column.type ?? 'text'}`);
  }

  /** Acciones que cambian `field` y que permite el ACL genérico. */
  private allowedActions(field: string) {
    return (this.definition().actions?.[field] ?? []).filter((action) => this.allowed(action.name));
  }

  private allowed(name: string): boolean {
    const acl = this.acl();
    return !!acl?.allAllowed || !!acl?.allows?.find((allow) => allow.name === name)?.allowed;
  }
}

/** Textos separados por comas o punto y coma, sin vacíos. */
function splitWords(text: string): string[] {
  return text
    .split(/[,;]/)
    .map((word) => word.trim())
    .filter((word) => !!word);
}
